    h,w=len(I),len(I[0])
    R=[r[:] for r in I]
    for _ in range(passes):
        for i in range(h):
            for j in range(w):
                cnt=defaultdict(int)
                for di in(-1,0,1):
                    for dj in(-1,0,1):
                        r,c=i+di,j+dj
                        if 0<=r<h and 0<=c<w and R[r][c]!=0: cnt[R[r][c]]+=1
                if cnt:
                    top=max(cnt.items(), key=lambda kv:(kv[1], kv[0]))[0]
                    if R[i][j]!=top: R[i][j]=top
    return R
